import type { AppQuestion } from './allQuestions';

export const tryoutQuestions: AppQuestion[] = [
  {"id":1001,"department":"Try Out UKMPPD 1","question":"Seorang anak laki-laki berusia 13 tahun dibawa ibunya ke poli mata dengan keluhan kedua mata sering tampak merah sejak 1 tahun terakhir. Pasien mengatakan penglihatan masih seperti biasa, namun terasa kurang nyaman karena mata sering mengeluarkan kotoran lengket, terutama ketika pagi hari. Diketahui ibu pasien memiliki riwayat asma. Pemeriksaan oftalmologi VODS 6/6, eksudat mukoid (+), hiperemis (+), tampak papil pada konjungtiva palpebra, funduskopi dbn. Apakah tatalaksana yang tepat sesuai keluhan pasien?","options":["Steroid oral","Antibiotik oral","Steroid topical","Antibiotik topikal","Antihistamin topikal"],"answer":4,"explanation":"Pasien ini menunjukkan gejala konjungtivitis alergi, yang ditandai dengan mata merah, eksudat mukoid, hiperemis, dan papil pada konjungtiva palpebra. Konjungtivitis alergi adalah reaksi inflamasi mata terhadap alergen, yang sering terjadi pada individu dengan riwayat alergi lain seperti asma, yang juga dimiliki oleh ibu pasien. Pengobatan utama untuk kondisi ini adalah dengan menghindari alergen dan penggunaan antihistamin topikal untuk mengurangi gejala alergi. - Mengapa Antihistamin Topikal (E) paling benar? Antihistamin topikal efektif untuk mengurangi gejala alergi pada mata dengan cara menghambat reseptor histamin, yang berperan dalam reaksi alergi. Ini membantu mengurangi kemerahan, gatal, dan produksi eksudat. - Mengapa opsi lain tidak tepat? - Steroid Oral (A) tidak tepat karena penggunaannya lebih cocok untuk kondisi inflamasi berat dan sistemik, bukan untuk konjungtivitis alergi yang relatif ringan dan lokal. - Antibiotik Oral (B) tidak tepat karena tidak ada infeksi bakteri yang terlibat dalam kasus ini; gejalanya disebabkan oleh alergi. - Steroid Topikal (C) bisa digunakan dalam kasus konjungtivitis alergi yang parah atau tidak responsif terhadap antihistamin, tetapi penggunaannya harus hati-hati karena risiko efek samping seperti peningkatan tekanan intraokular dan katarak. - Antibiotik Topikal (D) tidak tepat karena, seperti antibiotik oral, tidak ada indikasi penggunaannya dalam kasus alergi dimana tidak ada infeksi bakteri.","optionExplanations":["Steroid Oral tidak tepat karena penggunaannya lebih cocok untuk kondisi inflamasi berat dan sistemik, bukan untuk konjungtivitis alergi yang relatif ringan dan lokal.","Antibiotik Oral tidak tepat karena tidak ada infeksi bakteri yang terlibat dalam kasus ini; gejalanya disebabkan oleh alergi.","Steroid Topikal bisa digunakan dalam kasus konjungtivitis alergi yang parah atau tidak responsif terhadap antihistamin, tetapi penggunaannya harus hati-hati karena risiko efek samping seperti peningkatan tekanan intraokular dan katarak.","Antibiotik Topikal tidak tepat karena, seperti antibiotik oral, tidak ada indikasi penggunaannya dalam kasus alergi dimana tidak ada infeksi bakteri.","Pasien ini menunjukkan gejala konjungtivitis alergi, yang ditandai dengan mata merah, eksudat mukoid, hiperemis, dan papil pada konjungtiva palpebra. Pengobatan utama adalah menghindari alergen dan menggunakan antihistamin topikal. Antihistamin topikal efektif menghambat reseptor histamin sehingga membantu mengurangi kemerahan, gatal, dan produksi eksudat."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 1"},
  {"id":1002,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 28 tahun datang ke Puskesmas dengan keluhan mata kiri berair sejak 3 hari yang lalu. Pasien juga mengeluhkan adanya benjolan pada sudut mata bagian dalam dekat hidung yang sering mengeluarkan sekret berbau. Pada pemeriksaan fisik didapatkan tanda vital TD 120/80, HR 90, RR 18, T 37.4. Pada pemeriksaan status oftalmologis OS didapatkan VOS 6/6, tampak benjolan hiperemis, tenderness (+) di regio kantus medial. Apakah diagnosis yang paling mungkin?","options":["Kalazion","Hordeolum","Dakrioadenitis","Dakriostenosis","Dakriosistitis"],"answer":4,"explanation":"Dakriosistitis adalah infeksi pada kantung air mata yang terletak di antara sudut dalam mata dan hidung. Hal ini terjadi ketika ada penyumbatan pada nasolakrimal duct, menyebabkan akumulasi sekret yang kemudian terinfeksi. Pasien dengan dakriosistitis seringkali mengeluhkan adanya benjolan yang berair dan berbau di sudut mata bagian dalam dekat hidung, sesuai dengan keluhan pasien dalam soal. Tanda hiperemis dan tenderness di regio kantus medial juga mendukung diagnosis dakriosistitis. Mengapa opsi lain tidak tepat: A. Kalazion adalah penyumbatan pada kelenjar meibom yang terletak di kelopak mata, biasanya tidak disertai dengan infeksi akut dan sekret berbau. B. Hordeolum (stye) adalah infeksi akut pada kelenjar sebaceous di kelopak mata. Meskipun dapat menyebabkan benjolan dan nyeri, lokasinya biasanya tidak di kantus medial dan tidak terkait dengan sekret berbau. C. Dakrioadenitis adalah inflamasi pada kelenjar lakrimal, yang terletak di bagian luar atas mata, bukan di sudut dalam dekat hidung. D. Dakriostenosis adalah penyumbatan pada nasolakrimal duct tanpa infeksi, biasanya ditemukan pada bayi baru lahir dan tidak disertai dengan sekret berbau.","optionExplanations":["Kalazion adalah penyumbatan kelenjar meibom pada kelopak mata dan biasanya tidak menyebabkan infeksi akut atau sekret berbau.","Hordeolum merupakan infeksi akut kelenjar kelopak mata; lokasinya biasanya bukan di kantus medial dan tidak khas dengan sekret berbau.","Dakrioadenitis merupakan inflamasi kelenjar lakrimal yang berada di bagian superolateral orbita, bukan di sudut mata medial dekat hidung.","Dakriostenosis adalah sumbatan saluran nasolakrimal tanpa gambaran infeksi akut; sumber menyebut kondisi ini biasanya ditemukan pada bayi baru lahir.","Dakriosistitis merupakan infeksi kantung air mata akibat sumbatan nasolakrimal, sesuai dengan benjolan hiperemis, tenderness, dan sekret berbau di kantus medial."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 2"},
  {"id":1003,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 30 tahun datang ke poli mata keluhan mata kanan terasa nyeri dan kemerahan sejak 2 hari terakhir. Pasien bekerja sebagai petugas kebersihan pinggir jalan. Riwayat kemasukan benda asing disangkal namun pasien sering mengucek-kucek matanya. Pasien juga mengeluh mata sering berair dan terasa silau. Pemeriksaan OD visus 5/6, CI/PCI (+), kornea tampak keruh, BMD dalam, corpus alienum (-) seperti pada gambar. Apakah diagnosis yang tepat dari kasus tersebut?","options":["Konjungtivitis","Keratitis","Ulkus kornea","Glaukoma","Perdarahan subkonjungtiva"],"answer":1,"explanation":"Kasus ini menggambarkan seorang pasien dengan gejala nyeri mata, kemerahan, mata berair, dan terasa silau, yang merupakan gejala khas dari keratitis. Keratitis adalah inflamasi pada kornea yang dapat disebabkan oleh berbagai faktor, termasuk infeksi, trauma, paparan lingkungan yang ekstrem, dan penggunaan lensa kontak yang tidak tepat. Pada kasus ini, visus yang masih relatif baik (5/6) dan adanya kemerahan serta keruh pada kornea, tanpa adanya benda asing, menunjukkan keratitis sebagai diagnosis yang paling tepat. - Mengapa jawaban tersebut paling benar: Keratitis ditandai dengan adanya nyeri mata, kemerahan, penglihatan yang mungkin sedikit terganggu (tetapi tidak signifikan pada tahap awal), dan fotofobia (sensitivitas terhadap cahaya). Kornea yang keruh adalah tanda klasik dari keratitis. Pasien yang sering mengucek mata, terutama dalam kondisi kerja yang berdebu atau terpapar polutan, dapat meningkatkan risiko keratitis. - Mengapa opsi lain tidak tepat: A. Konjungtivitis biasanya ditandai dengan mata merah dan sekresi, tetapi tidak menyebabkan keruhnya kornea atau nyeri yang signifikan. C. Ulkus kornea adalah kerusakan lebih lanjut dari keratitis yang menyebabkan luka pada kornea. Tanpa informasi lebih lanjut tentang adanya defek ulseratif pada kornea, keratitis lebih tepat sebagai diagnosis awal. D. Glaukoma biasanya tidak menyebabkan kemerahan dan keruh pada kornea sebagai gejala utama. Glaukoma lebih sering dikaitkan dengan peningkatan tekanan intraokular dan kerusakan saraf optik. E. Perdarahan subkonjungtiva adalah kondisi di mana pembuluh darah di bawah konjungtiva pecah, menyebabkan area merah cerah pada mata, tetapi tidak menyebabkan nyeri, keruhnya kornea, atau fotofobia.","optionExplanations":["Konjungtivitis biasanya ditandai mata merah dan sekresi, tetapi sumber menekankan bahwa kondisi ini tidak menyebabkan kornea keruh atau nyeri signifikan.","Keratitis paling sesuai dengan nyeri, kemerahan, fotofobia, mata berair, dan kornea keruh tanpa corpus alienum.","Ulkus kornea merupakan kerusakan lebih lanjut dari keratitis yang menimbulkan defek ulseratif; sumber tidak memberikan informasi tentang defek ulseratif pada kasus ini.","Glaukoma tidak sesuai dengan temuan utama berupa kornea keruh dan fotofobia; sumber mengaitkannya dengan peningkatan tekanan intraokular dan kerusakan saraf optik.","Perdarahan subkonjungtiva menyebabkan area merah cerah, tetapi tidak menjelaskan nyeri, kornea keruh, atau fotofobia."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 3","image":"/images/tryout1-q3.svg"},
  {"id":1004,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 27 tahun datang ke poliklinik RS dengan keluhan benjolan pada kelopak mata kiri atas. Hal ini telah dirasakannya sejak 1 bulan ini. Pasien menyangkal adanya rasa nyeri. Dari pemeriksaan mata, dijumpai visus ODS 6/6, terdapat benjolan sewarna kulit pada kelopak bawah mata kanan, nyeri tekan (-). Apakah tatalaksana yang paling tepat?","options":["Insisi vertikal","Insisi horizontal","Ekokleasi","Drainase","Masase sakus"],"answer":2,"explanation":"Benjolan pada kelopak mata yang sewarna dengan kulit dan tidak nyeri pada tekan, seperti yang dijelaskan dalam kasus ini, sangat mungkin merupakan kasus kista meibom atau chalazion. Chalazion terjadi karena penyumbatan pada kelenjar Meibom, yang menghasilkan lipid untuk film air mata. Penyumbatan ini menyebabkan akumulasi sekret yang tidak dapat keluar, membentuk benjolan. Pilihan tatalaksana untuk chalazion tergantung pada ukuran dan gejala yang ditimbulkan. Ekokleasi, yang merupakan jawaban paling tepat dalam kasus ini, adalah prosedur pengangkatan isi kista dengan menggunakan alat khusus setelah dilakukan insisi kecil. Prosedur ini efektif untuk menghilangkan benjolan tanpa meninggalkan bekas yang signifikan dan memiliki risiko komplikasi yang rendah. Mengapa opsi lain tidak tepat: A. Insisi vertikal dan B. Insisi horizontal tidak tepat karena insisi semacam ini biasanya digunakan untuk kondisi yang memerlukan akses yang lebih luas atau drainase abses, bukan untuk chalazion yang lebih cocok dengan ekokleasi. D. Drainase mungkin terdengar mirip dengan ekokleasi, namun drainase biasanya digunakan untuk abses atau kumpulan cairan yang memerlukan pengeluaran cairan. Chalazion bukanlah abses dan memiliki konsistensi yang lebih padat yang tidak bisa hanya drenasi. E. Masase sakus dilakukan untuk kondisi tertentu yang melibatkan kelenjar lakrimal atau untuk membantu mengatasi penyumbatan pada saluran air mata, bukan untuk mengatasi chalazion. Subtopik medis yang diujikan di sini adalah mengenai pengelolaan lesi kelopak mata, khususnya chalazion. Penting untuk membedakan antara chalazion dengan kondisi lain seperti hordeolum (stye) yang merupakan infeksi akut pada kelenjar sebaceous kelopak mata, yang mana tatalaksananya bisa berbeda. Ekokleasi menjadi pilihan yang tepat karena langsung mengatasi penyebab masalah dengan mengeluarkan isi kista secara efektif.","optionExplanations":["Insisi vertikal tidak dipilih menurut pembahasan sumber karena insisi tersebut biasanya digunakan untuk kondisi yang memerlukan akses lebih luas atau drainase abses, bukan chalazion.","Insisi horizontal juga tidak dipilih menurut pembahasan sumber karena lebih terkait akses luas atau drainase abses, sedangkan chalazion lebih cocok dengan ekokleasi.","Ekokleasi adalah kunci pada sumber; prosedur ini mengangkat isi kista/chalazion setelah insisi kecil dan bertujuan menghilangkan benjolan secara efektif.","Drainase biasanya digunakan untuk abses atau kumpulan cairan; sumber menyebut chalazion lebih padat dan tidak cukup ditangani hanya dengan drainase.","Masase sakus digunakan untuk kondisi yang melibatkan kelenjar lakrimal atau membantu sumbatan saluran air mata, bukan untuk chalazion."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 4","image":"/images/tryout1-q4.svg"},
  {"id":1005,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 58 tahun datang ke poli mata dengan keluhan kedua mata terasa mengganjal. Keluhan dirasakan sudah sejak 3 tahun terakhir sejak menopause dan memberat ketika berada di ruangan ber-AC, dimana mata tampak merah dan berair. Pada pemeriksaan fisik visus ODS 6/6, konjungtiva hiperemis, pemeriksaan slit-lamp menunjukkan filamen-filamen putih pada kornea superior. Apakah tatalaksana yang tepat pada kasus tersebut?","options":["Kompres hangat","Artificial tears","Kloramfenikol","Natamisin","Asiklovir"],"answer":1,"explanation":"Kasus ini menggambarkan gejala dari sindrom mata kering (Dry Eye Syndrome) atau keratoconjunctivitis sicca, yang sering terjadi pada wanita pasca-menopause akibat perubahan hormonal yang mempengaruhi produksi air mata. Gejala yang dialami pasien seperti mata terasa mengganjal, merah, berair ketika berada di ruangan ber-AC, dan adanya filamen putih pada kornea superior adalah karakteristik dari kondisi ini. Mengapa B (Artificial tears) paling benar: Artificial tears atau air mata buatan adalah pilihan terapi utama untuk sindrom mata kering. Mereka bertindak sebagai pelumas dan menggantikan kelembapan yang hilang pada permukaan mata, mengurangi gejala iritasi dan ketidaknyamanan. Mengapa opsi lain tidak tepat: A. Kompres hangat biasanya digunakan untuk mengobati penyumbatan kelenjar Meibomius, bukan untuk sindrom mata kering secara langsung. C. Kloramfenikol adalah antibiotik yang digunakan untuk mengobati infeksi bakteri pada mata, bukan untuk sindrom mata kering. D. Natamisin adalah antijamur yang digunakan untuk mengobati infeksi jamur pada mata, tidak relevan dengan kasus sindrom mata kering. E. Asiklovir digunakan untuk mengobati infeksi virus pada mata, seperti herpes simplex keratitis, bukan untuk sindrom mata kering.","optionExplanations":["Kompres hangat menurut sumber lebih digunakan untuk penyumbatan kelenjar Meibomius, bukan terapi utama sindrom mata kering.","Artificial tears merupakan terapi utama sindrom mata kering karena melumasi dan menggantikan kelembapan permukaan mata.","Kloramfenikol adalah antibiotik untuk infeksi bakteri mata dan tidak sesuai untuk sindrom mata kering.","Natamisin adalah antijamur untuk infeksi jamur mata dan tidak relevan dengan sindrom mata kering.","Asiklovir digunakan untuk infeksi virus mata seperti herpes simplex keratitis, bukan untuk sindrom mata kering."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 5"},
  {"id":1006,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 30 tahun datang ke IGD RS dengan keluhan pandangan mata kanan kabur secara tiba-tiba sejak 30 menit yang lalu. Pasien juga mengeluhkan nyeri kepala hebat dan mual-muntah tanpa diketahui penyebabnya. Pemeriksaan visus OD 1/60, OS 6/6. Pemeriksaan lokalisata dijumpai mata merah, injeksi konjungtiva (+), injeksi siliar (+), edema kornea, pupil mid-dilatasi, funduskopi C/D ratio 0,6. Apakah tatalaksana yang tepat dari keluhan pasien?","options":["Agonis alfa","Karbonik anhidrase oral","Penyekat beta topikal","Prostaglandin analog","Diuretik"],"answer":1,"explanation":"Pasien dalam soal ini menunjukkan gejala klasik dari glaukoma sudut tertutup akut (GSA), yang ditandai dengan pandangan kabur mendadak, nyeri kepala hebat, mual-muntah, mata merah, injeksi konjungtiva, injeksi siliar, edema kornea, pupil mid-dilatasi, dan peningkatan rasio cup-to-disc (C/D ratio) pada funduskopi. Tatalaksana awal untuk GSA bertujuan untuk menurunkan tekanan intraokular (TIO) dengan cepat. A. Agonis alfa - Meskipun agonis alfa seperti apraclonidine dapat menurunkan TIO dengan mengurangi produksi humor akuus dan meningkatkan aliran keluar uveoskleral, mereka bukan pilihan pertama dalam pengelolaan awal GSA karena onset kerjanya lebih lambat dibandingkan dengan opsi lain. B. Karbonik anhidrase oral - Inhibitor karbonik anhidrase seperti asetazolamid bekerja dengan cepat untuk menurunkan produksi humor akuus, sehingga menurunkan TIO. Ini adalah pilihan yang tepat untuk manajemen awal GSA karena efeknya yang cepat dan efektif dalam menurunkan tekanan intraokular. C. Penyekat beta topikal - Penyekat beta topikal seperti timolol juga digunakan untuk menurunkan TIO dengan mengurangi produksi humor akuus. Meskipun efektif, onset kerjanya tidak secepat inhibitor karbonik anhidrase dalam pengelolaan awal GSA. D. Prostaglandin analog - Prostaglandin analog seperti latanoprost meningkatkan aliran keluar humor akuus melalui jalur uveoskleral. Mereka sangat efektif dalam mengelola glaukoma kronis tetapi tidak ideal untuk manajemen awal GSA karena onset kerja yang lebih lambat. E. Diuretik - Diuretik dapat digunakan untuk menurunkan TIO dalam beberapa kasus, tetapi dalam konteks GSA, inhibitor karbonik anhidrase oral lebih disukai karena mekanisme kerja spesifiknya yang menargetkan produksi humor akuus. Subtopik medis yang diujikan di sini adalah glaukoma sudut tertutup akut, suatu keadaan darurat oftalmologi yang memerlukan penurunan tekanan intraokular dengan cepat untuk mencegah kerusakan permanen pada saraf optik dan kehilangan penglihatan. Pengenalan cepat dan tatalaksana yang tepat sangat penting untuk hasil yang baik.","optionExplanations":["Agonis alfa dapat menurunkan TIO, tetapi sumber menyebutnya bukan pilihan pertama dalam pengelolaan awal GSA karena onset lebih lambat dibandingkan pilihan lain.","Karbonik anhidrase oral seperti asetazolamid bekerja cepat menurunkan produksi humor akuus dan merupakan pilihan yang tepat untuk manajemen awal GSA menurut sumber.","Penyekat beta topikal seperti timolol menurunkan produksi humor akuus, tetapi sumber menyebut onsetnya tidak secepat inhibitor karbonik anhidrase pada awal GSA.","Prostaglandin analog meningkatkan aliran keluar uveoskleral dan lebih efektif pada glaukoma kronis; sumber tidak menempatkannya sebagai pilihan ideal untuk fase awal GSA.","Diuretik dapat menurunkan TIO pada beberapa keadaan, tetapi sumber lebih memilih inhibitor karbonik anhidrase oral pada konteks GSA."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 6"},
  {"id":1007,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 59 tahun datang ke poliklinik RS dengan keluhan nyeri pada mata kiri. Hal ini telah dialami pasien sejak 1 bulan yang lalu. Rasa nyeri juga disertai dengan keluhan mata merah dan berair. Pada pemeriksaan tanda vital dalam batas normal. Pemeriksaan oftalmologi dijumpai bulu mata pada mata kiri pasien tumbuh ke arah dalam, margin palpebra dalam batas normal. Apakah tatalaksana yang sesuai?","options":["Trabekulektomi","Insisi","Enukleasi","Ekokleasi","Epilasi"],"answer":4,"explanation":"Pasien dalam soal ini mengalami kondisi di mana bulu mata tumbuh ke arah dalam, yang dikenal dengan istilah trichiasis. Trichiasis adalah kondisi yang dapat menyebabkan iritasi pada mata, nyeri, mata merah, dan berair, seperti yang dialami oleh pasien. Tatalaksana yang paling tepat untuk kondisi ini adalah epilasi, yaitu prosedur pengangkatan bulu mata yang tumbuh ke arah dalam. Epilasi dapat dilakukan dengan pinset atau dengan metode elektrolisis. Proses ini membantu mengurangi iritasi pada mata yang disebabkan oleh gesekan bulu mata terhadap permukaan mata. Mengapa opsi lain tidak tepat: A. Trabekulektomi adalah prosedur bedah yang dilakukan untuk mengurangi tekanan intraokular pada pasien dengan glaukoma, tidak terkait dengan trichiasis. B. Insisi biasanya digunakan untuk mengeluarkan abses atau benda asing, tidak sesuai untuk kondisi trichiasis. C. Enukleasi adalah pengangkatan bola mata, yang merupakan tindakan ekstrem dan tidak sesuai untuk kondisi seperti trichiasis. D. Ekokleasi adalah prosedur pengangkatan isi bola mata tanpa mengangkat selubung terluarnya, biasanya dilakukan pada kondisi tertentu seperti endoftalmitis berat atau tumor intraokular. Ini juga tidak relevan dengan kasus trichiasis.","optionExplanations":["Trabekulektomi dilakukan untuk menurunkan tekanan intraokular pada glaukoma, bukan untuk trichiasis.","Insisi biasanya digunakan untuk mengeluarkan abses atau benda asing dan tidak sesuai untuk bulu mata yang tumbuh ke arah dalam.","Enukleasi adalah pengangkatan bola mata dan merupakan tindakan ekstrem yang tidak sesuai untuk trichiasis.","Ekokleasi adalah pengangkatan isi bola mata dengan mempertahankan selubung luar dan tidak relevan untuk trichiasis.","Epilasi adalah pengangkatan bulu mata yang tumbuh ke arah dalam; sumber menyebutnya sebagai tatalaksana yang tepat untuk trichiasis."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 7"},
  {"id":1008,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 60 tahun, datang ke poli mata dengan keluhan penglihatan kedua mata kabur. Hal ini dialami pasien sejak 5 bulan yang lalu namun kini pasien merasa terganggu saat beraktivitas. Pasien memiliki riwayat hipertensi dan DM sejak 10 tahun yang lalu namun jarang mengambil obat ke puskesmas karena seringkali tidak ada yang mengantarnya. Pemeriksaan oftalmologis OD 2/6, OS 4/6, pinhole (-). Pemeriksaan funduskopi didapatkan reflex fundus (+), cotton wool spot, AV nicking, perdarahan pada vitreus, neovaskularisasi (-). Apakah diagnosis yang paling tepat?","options":["Central Retinal Artery Occlusion","Hypertension Retinopathy","Non-proliferative Diabetic Retinopathy","Central Retinal Vein Occlusion","Age-Related Macular Degeneration"],"answer":1,"explanation":"Hypertension Retinopathy adalah kondisi yang terjadi akibat kerusakan pada retina yang disebabkan oleh tekanan darah tinggi (hipertensi). Dalam kasus ini, pasien memiliki riwayat hipertensi dan diabetes melitus (DM) yang tidak terkontrol, yang keduanya merupakan faktor risiko utama untuk retinopati hipertensi. Temuan klinis seperti cotton wool spot, AV nicking (penyempitan vena di retina yang disebabkan oleh arteri yang mengeras atau menyempit), dan perdarahan pada vitreus adalah karakteristik dari retinopati hipertensi. Reflex fundus yang positif juga mendukung diagnosis ini. Mengapa opsi lain tidak tepat: A. Central Retinal Artery Occlusion (CRAO) biasanya menyebabkan hilangnya penglihatan yang tiba-tiba dan nyata pada satu mata, bukan penglihatan kabur bertahap pada kedua mata. Tidak ada temuan khas CRAO seperti cherry-red spot pada kasus ini. C. Non-proliferative Diabetic Retinopathy (NPDR) adalah tahap awal dari retinopati diabetik yang dapat menunjukkan beberapa temuan serupa seperti cotton wool spot, namun neovaskularisasi (-) menunjukkan bahwa kondisi ini belum mencapai tahap proliferatif, yang lebih sering dikaitkan dengan DM. Meskipun pasien memiliki DM, temuan klinis lebih konsisten dengan retinopati hipertensi. D. Central Retinal Vein Occlusion (CRVO) menyebabkan edema dan perdarahan di retina, namun biasanya akan menunjukkan tanda-tanda seperti disk edema yang tidak disebutkan dalam kasus ini. E. Age-Related Macular Degeneration (AMD) berkaitan dengan usia dan mempengaruhi visi sentral, namun tidak ditandai dengan cotton wool spot atau AV nicking, yang lebih khas untuk kerusakan vaskular akibat hipertensi.","optionExplanations":["CRAO biasanya menyebabkan kehilangan penglihatan yang tiba-tiba dan nyata pada satu mata serta dapat menunjukkan cherry-red spot; gambaran ini tidak disebutkan.","Retinopati hipertensi sesuai dengan riwayat hipertensi dan temuan cotton wool spot serta AV nicking yang ditekankan dalam sumber.","NPDR dapat memiliki beberapa temuan yang mirip, tetapi sumber menilai gambaran klinis lebih konsisten dengan retinopati hipertensi.","CRVO menyebabkan edema dan perdarahan retina; sumber menyebut disk edema sebagai temuan yang biasanya menyertai dan tidak disebutkan pada kasus.","AMD terutama memengaruhi penglihatan sentral dan tidak khas dengan cotton wool spot atau AV nicking."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 8"},
  {"id":1009,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 37 tahun datang ke IGD dengan keluhan penglihatan mata kirinya kabur mendadak sejak 30 menit yang lalu. Pasien mengaku sedang mengendarai motor namun tidak memakai helm, tiba-tiba ia merasakan ada sesuatu masuk ke mata kirinya. Pasien mengatakan mata juga merah dan terasa silau. Keluhan nyeri kepala dan mual muntah disangkal. Status lokalis tampak seperti gambar, VOD 6/6, VOS 3/6. Apakah diagnosis dari keluhan pasien?","options":["Corpus alienum konjungtiva","Corpus alienum kornea","Corpus alienum iris","Corpus alienum sklera","Corpus alienum COA"],"answer":1,"explanation":"Pasien mengalami penglihatan kabur mendadak setelah merasakan ada sesuatu masuk ke mata, disertai kemerahan dan silau. Gejala ini mengindikasikan adanya benda asing di kornea, yang dapat menyebabkan iritasi dan gangguan penglihatan. VOD 6/6 menunjukkan penglihatan baik pada mata kanan, sedangkan VOS 3/6 menunjukkan gangguan pada mata kiri, yang konsisten dengan adanya corpus alienum di kornea. Pilihan lainnya kurang tepat karena: A. Corpus alienum konjungtiva: Biasanya tidak menyebabkan penglihatan kabur yang signifikan. C. Corpus alienum iris: Tidak mungkin menyebabkan penglihatan kabur mendadak tanpa nyeri kepala atau mual. D. Corpus alienum sklera: Lebih jarang terjadi dan tidak sesuai dengan gejala yang disampaikan. E. Corpus alienum COA: Istilah ini tidak umum dan tidak relevan dengan kasus ini.","optionExplanations":["Corpus alienum konjungtiva biasanya tidak menyebabkan penglihatan kabur yang signifikan menurut pembahasan sumber.","Corpus alienum kornea paling sesuai dengan sensasi benda asing, kemerahan, silau, dan penurunan visus pada mata kiri.","Corpus alienum iris dinilai kurang sesuai oleh pembahasan sumber dengan gambaran klinis yang diberikan.","Corpus alienum sklera lebih jarang dan tidak sesuai dengan gejala yang disampaikan.","Corpus alienum COA disebut tidak umum dan tidak relevan dengan kasus ini oleh sumber."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 9","image":"/images/tryout1-q9.svg"},
  {"id":1010,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 60 tahun datang ke puskesmas dengan keluhan nyeri pada kaki kanan sejak 1 minggu yang memberat sejak kemarin. Keluhan disertai demam. Pemeriksaan tanda vital TD 110/70, HR 80, RR 20, T 38,4. Pemeriksaan dermatologis didapatkan patch eritematosa, batas tegas, teraba hangat kruris dextra. Pemeriksaan laboratorium didapatkan leukosit 18.000. Diagnosis yang tepat untuk pasien adalah? 4","options":["Selulitis","Ektima","Erisipelas","Eritrasma","Flegmon"],"answer":2,"explanation":"Erisipelas adalah infeksi bakteri akut pada dermis yang menyebabkan peradangan pada lapisan kulit. Penyakit ini ditandai dengan adanya area eritematosa (kemerahan), dengan batas yang tegas, teraba hangat, dan seringkali disertai demam serta peningkatan jumlah leukosit (leukositosis) seperti yang terjadi pada kasus ini. Erisipelas biasanya disebabkan oleh Streptococcus pyogenes. Penyakit ini memerlukan penanganan dengan antibiotik untuk mencegah komplikasi. Mengapa opsi lain tidak tepat: A. Selulitis adalah infeksi bakteri yang lebih dalam dibandingkan erisipelas, mempengaruhi lapisan kulit subkutan. Meskipun gejalanya mirip dengan erisipelas, selulitis biasanya memiliki batas yang kurang tegas dan lebih sering terjadi pada kaki. B. Ektima adalah infeksi kulit yang lebih dalam lagi, yang mencapai dermis dan subkutan, seringkali meninggalkan ulkus (luka terbuka) setelah sembuh. Tidak ada deskripsi ulkus pada kasus ini. D. Eritrasma adalah infeksi bakteri superfisial yang disebabkan oleh Corynebacterium minutissimum, biasanya ditandai dengan patch eritematosa yang halus tanpa demam atau leukositosis signifikan. E. Flegmon adalah infeksi bakteri yang menyebar di jaringan lunak, tanpa batas yang jelas antara jaringan yang terinfeksi dan yang tidak, berbeda dengan erisipelas yang memiliki batas tegas.","optionExplanations":["Selulitis mengenai lapisan yang lebih dalam/subkutan dan biasanya memiliki batas kurang tegas dibandingkan erisipelas.","Ektima mencapai dermis dan subkutan serta sering meninggalkan ulkus; deskripsi ulkus tidak ada pada kasus ini.","Erisipelas sesuai dengan patch eritematosa berbatas tegas, hangat, disertai demam dan leukositosis.","Eritrasma merupakan infeksi superfisial dan sumber menyebutnya biasanya berupa patch eritematosa halus tanpa demam atau leukositosis signifikan.","Flegmon menyebar pada jaringan lunak tanpa batas jelas, berbeda dengan erisipelas yang berbatas tegas."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 10","image":null},
  {"id":1011,"department":"Try Out UKMPPD 1","question":"Seorang anak laki-laki berusia 10 tahun datang ke puskesmas bersama orang tuanya dengan keluhan bercak putih pada pipi kiri. Bercak dirasa gatal yang memberat terutama saat berkeringat setelah bermain bola di bawah terik matahari. Pemeriksaan tanda vital TD 100/70, HR 80, RR 24, T 36,4. Pemeriksaan lokalis didapatkan makula hipopigmentasi berbatas tegas disertai skuama halus diatasnya. Pemeriksaan lampu wood memberikan warna kuning keemasan. Tatalaksana yang tepat untuk pasien adalah?","options":["Rivanol 1%","Mikonazol 2%","Asam fusidat 2%","Asiklovir 3%","Ketokonazol 8%"],"answer":1,"explanation":"Jawaban: B Pembahasan: Anak tersebut memiliki gejala yang konsisten dengan tinea versicolor (pitiriasis versikolor), yaitu infeksi jamur superfisial yang ditandai dengan bercak hipopigmentasi berbatas tegas yang disertai skuama halus dan berwarna kuning keemasan saat diperiksa dengan lampu Wood. Mikonazol 2% adalah antijamur topikal yang efektif untuk mengobati tinea versicolor. Rivanol 1% (A) adalah antiseptik dan tidak efektif untuk mengobati infeksi jamur. Asam fusidat 2% (C) adalah antibiotik topikal yang digunakan untuk mengobati infeksi bakteri kulit, bukan jamur. Asiklovir 3% (D) adalah antiviral yang digunakan untuk mengobati infeksi virus herpes, bukan jamur. Ketokonazol 8% (E) juga merupakan antijamur, tetapi konsentrasi 8% biasanya digunakan untuk pengobatan sistemik, bukan topikal.","optionExplanations":["Rivanol 1% adalah antiseptik dan tidak efektif untuk mengobati infeksi jamur.","Mikonazol 2% adalah antijamur topikal yang efektif untuk mengobati tinea versicolor/pitiriasis versikolor.","Asam fusidat 2% adalah antibiotik topikal untuk infeksi bakteri kulit, bukan jamur.","Asiklovir 3% adalah antiviral untuk infeksi virus herpes, bukan untuk tinea versicolor.","Ketokonazol 8% disebut sumber sebagai antijamur, tetapi konsentrasi tersebut dinyatakan biasanya untuk pengobatan sistemik, bukan topikal."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 11"},
  {"id":1012,"department":"Try Out UKMPPD 1","question":"Seorang laki-laki berusia 15 tahun datang ke rumah sakit dibawa oleh ibunya dengan keluhan nyeri pada kaki kanan sejak 1 minggu yang lalu. Riwayat pasien tertusuk duri yang terjadi berulang kali dalam 2 bulan terakhir pada kaki. Pemeriksaan tanda vital TD 110/70, HR 80, RR 20, T 36,5. Pemeriksaan dermatologis didapatkan krusta tebal kekuningan dengan dasar ulkus dangkal. Tatalaksana yang tepat untuk pasien adalah?","options":["Emolien","Ketokonazol 2%","Mupirocin 2%","Terbinafin 1%","Asam fusidat 1%"],"answer":2,"explanation":"Jawaban: C. Mupirocin 2% Pembahasan: Pasien dengan riwayat tertusuk duri berulang kali dan ditemukan ulkus dangkal dengan krusta tebal kekuningan menunjukkan infeksi bakteri pada kulit, yang kemungkinan besar disebabkan oleh Staphylococcus aureus atau Streptococcus pyogenes. Mupirocin adalah antibiotik topikal yang efektif melawan kedua jenis bakteri tersebut, sehingga merupakan pilihan terbaik untuk tatalaksana pasien ini. Emolien (A) biasanya digunakan untuk melembabkan kulit yang kering dan tidak efektif melawan infeksi bakteri. Ketokonazol (B) dan terbinafin (D) adalah antifungal, yang tidak efektif melawan bakteri. Asam fusidat (E) adalah antibiotik yang efektif melawan Staphylococcus, tetapi kurang efektif melawan Streptococcus dibandingkan mupirocin.","optionExplanations":["Emolien digunakan untuk melembabkan kulit kering dan tidak efektif melawan infeksi bakteri.","Ketokonazol adalah antijamur dan tidak efektif melawan infeksi bakteri pada kasus ini.","Mupirocin 2% merupakan antibiotik topikal yang menurut sumber efektif melawan Staphylococcus aureus dan Streptococcus pyogenes serta menjadi pilihan terbaik.","Terbinafin adalah antijamur dan tidak efektif melawan infeksi bakteri pada kasus ini.","Asam fusidat efektif terhadap Staphylococcus, tetapi sumber menyatakan kurang efektif terhadap Streptococcus dibandingkan mupirocin."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 12","image":"/images/tryout1-q12.svg"},
  {"id":1013,"department":"Try Out UKMPPD 1","question":"Seorang pria berusia 68 tahun datang ke puskesmas dengan keluhan didapatkan bercak dengan warna coklat pada wajah. Pasien merupakan seorang petani dan mengaku jarang memakai tabir surya. Pemeriksaan tanda vital TD 120/80, HR 90, RR 20, T 36,2. pada pemeriksaan status lokalis didapatkan plak berwarna coklat hingga hitam multipel, bentuk asimetris dengan tepi ireguler. Asal sel yang mengalami metaplasia adalah?","options":["Sel keratinosit","Sel melanosit","Sel basal","Sel endotel","Sel lipid"],"answer":1,"explanation":"Jawaban: B. Sel melanosit Pembahasan: Pasien dengan riwayat paparan sinar matahari yang berlebihan dan jarang menggunakan tabir surya memiliki risiko tinggi terhadap melanoma, yaitu kanker kulit yang berasal dari sel melanosit. Deskripsi lesi yang asimetris, berwarna coklat hingga hitam, dan tepi yang ireguler adalah ciri khas melanoma. Metaplasia adalah perubahan dari satu jenis sel dewasa menjadi jenis sel dewasa lainnya, dan dalam konteks ini, sel melanosit yang berubah menjadi sel kanker. Jawaban lainnya kurang tepat karena: A. Sel keratinosit: Metaplasia sel keratinosit biasanya terjadi dalam konteks kanker kulit sel skuamosa, bukan melanoma. C. Sel basal: Metaplasia sel basal biasanya terjadi dalam konteks karsinoma sel basal, bukan melanoma. D. Sel endotel: Metaplasia sel endotel biasanya terjadi dalam konteks penyakit vaskular, bukan melanoma. E. Sel lipid: Metaplasia sel lipid biasanya terjadi dalam konteks penyakit metabolik, bukan melanoma.","optionExplanations":["Sel keratinosit bukan sel asal melanoma menurut pembahasan sumber; melanoma berasal dari melanosit.","Sel melanosit merupakan asal melanoma menurut pembahasan sumber dan sesuai dengan lesi asimetris coklat-hitam bertepi ireguler.","Sel basal dikaitkan sumber dengan karsinoma sel basal, bukan melanoma.","Sel endotel dikaitkan sumber dengan penyakit vaskular, bukan melanoma.","Sel lipid dikaitkan sumber dengan penyakit metabolik, bukan melanoma."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 13"},
  {"id":1014,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 45 tahun datang ke IGD RS dengan dengan keluhan muncul kemerahan dan lentingan pada wajah. Keluhan lain terdapat mata merah yang berair, namun tidak mengalami gangguan penglihatan. Dan terdapat keluhan sariawan pada rongga mulut. Riwayat pasien mengkonsumsi obat anti nyeri 2 hari lalu. Pemeriksaan tanda vital TD 80/50, HR 120, RR 20, T 36,2. Pemeriksaan status lokalis pada regio facialis terdapat makula eritematosa difus, berkonfluens disertai bula multipel, nikolsky sign (+). Pada mukosa mulut terdapat ulkus multipel. Diagnosis yang tepat adalah?","options":["Lyell’s syndrome","SJS","SJS-TEN","Pemfigus vulgaris","Pemfigoid bulosa"],"answer":1,"explanation":"Soal ini menampilkan seorang wanita dengan gejala klinis yang mencakup kemerahan dan lentingan pada wajah, mata merah berair, serta sariawan di mulut setelah mengonsumsi obat anti nyeri. Tanda vital menunjukkan hipotensi dan takikardia, sementara pemeriksaan fisik menunjukkan adanya makula eritematosa difus dengan bula multipel dan Nikolsky sign positif. Gejala-gejala ini, terutama setelah konsumsi obat, sangat khas untuk sindrom Stevens-Johnson (SJS). SJS adalah reaksi hipersensitivitas yang serius, sering dipicu oleh obat-obatan, yang ditandai dengan lesi kulit dan mukosa yang parah. Nikolsky sign positif menunjukkan adanya pemisahan epidermis yang konsisten dengan SJS. Pilihan lain kurang tepat karena: A. Lyell’s syndrome (Toxic Epidermal Necrolysis - TEN): Kondisi ini mirip dengan SJS tetapi lebih parah, dengan detasemen epidermis yang lebih luas, biasanya lebih dari 30% dari permukaan tubuh. Dalam kasus ini, tidak ada indikasi bahwa area yang terkena mencapai tingkat ini, sehingga lebih sesuai dengan SJS. C. SJS-TEN overlap: Ini adalah kondisi di mana detasemen epidermis melibatkan 10-30% dari permukaan tubuh. Meskipun pasien memiliki gejala yang parah, tidak ada informasi yang menunjukkan bahwa luas area yang terkena mencapai tingkat ini, sehingga lebih tepat untuk mendiagnosisnya sebagai SJS. D. Pemfigus vulgaris: Penyakit autoimun ini ditandai dengan bula intraepidermal yang sering melibatkan kulit dan mukosa, serta Nikolsky sign positif. Namun, pemfigus vulgaris tidak biasanya dipicu oleh obat dan tidak disertai dengan gejala sistemik akut seperti hipotensi dan takikardia yang terlihat pada kasus ini. E. Pemfigoid bulosa: Ini adalah penyakit autoimun yang menyebabkan bula subepidermal, biasanya pada orang tua, dan tidak terkait dengan Nikolsky sign positif. Selain itu, pemfigoid bulosa jarang melibatkan mukosa dan tidak dipicu oleh obat-obatan dengan cara yang sama seperti SJS. Dengan mempertimbangkan gejala klinis dan riwayat konsumsi obat, diagnosis yang paling tepat adalah sindrom Stevens-Johnson.","optionExplanations":["Lyell’s syndrome/TEN lebih berat daripada SJS dan menurut sumber biasanya melibatkan detasemen epidermis >30% permukaan tubuh; luas tersebut tidak ditunjukkan pada kasus.","SJS sesuai dengan lesi kulit dan mukosa setelah konsumsi obat, Nikolsky sign positif, hipotensi, dan takikardia yang dijelaskan sumber.","SJS-TEN overlap melibatkan detasemen epidermis 10–30%; sumber menyatakan tidak ada informasi yang menunjukkan luas tersebut pada kasus.","Pemfigus vulgaris dapat mengenai kulit dan mukosa serta Nikolsky positif, tetapi sumber menilai tidak sesuai dengan pemicu obat dan gambaran sistemik akut kasus ini.","Pemfigoid bulosa biasanya pada orang tua, bula subepidermal, jarang melibatkan mukosa, dan menurut sumber tidak sesuai dengan kasus ini."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 14"},
  {"id":1015,"department":"Try Out UKMPPD 1","question":"Seorang pria berusia 30 tahun datang ke IGD RS dengan dengan keluhan muncul kemerahan dan lentingan pada hampir seluruh tubuh. Keluhan lain terdapat mata merah yang berair. Keluhan sariawan pada rongga mulut dan nyeri saat menelan. Riwayat pasien mengkonsumsi fenitoin. Pemeriksaan tanda vital TD 85/60, HR 140, RR 24, T 36,5. Pemeriksaan status lokalis terdapat makula eritematosa difus, berkonfluens disertai bula hipopion multipel, nikolsky sign (+), erosi hemoragik multipel generalisata. Diagnosis yang tepat adalah?","options":["Stevens-Johnson Syndrome","Pemfigus vulgaris","Staphylococcal scalded skin syndrome","Toxic epidermal necrolysis","Pemfigoid bulosa"],"answer":3,"explanation":"Jawaban: D Pembahasan: Pasien ini didiagnosis dengan Toxic Epidermal Necrolysis (TEN). TEN adalah reaksi kulit yang parah dan berpotensi mengancam jiwa yang biasanya disebabkan oleh reaksi obat, dalam hal ini fenitoin. Gejala klinis TEN meliputi demam, rasa tidak nyaman atau sakit pada kulit, dan kemudian muncul ruam merah atau ungu yang cepat menyebar dan membentuk lepuh. Lepuh ini dapat pecah dan menyebabkan erosi dan eksfoliasi kulit. TEN juga dapat mempengaruhi membran mukosa, seperti mata dan mulut, yang dapat menyebabkan mata merah dan berair serta sariawan. Pilihan lain kurang tepat karena: A. Stevens-Johnson Syndrome (SJS) adalah bentuk ringan dari TEN dan biasanya hanya mempengaruhi <10% permukaan tubuh. Pasien ini memiliki lesi yang lebih luas yang mencakup hampir seluruh tubuh, yang lebih konsisten dengan TEN. B. Pemfigus vulgaris adalah penyakit autoimun yang menyebabkan lepuh pada kulit dan membran mukosa, tetapi tidak biasanya disebabkan oleh obat dan tidak disertai dengan tanda vital yang abnormal seperti yang ditemukan pada pasien ini. C. Staphylococcal Scalded Skin Syndrome (SSSS) adalah infeksi bakteri yang menyebabkan eksfoliasi kulit, tetapi biasanya terjadi pada bayi dan anak-anak, bukan orang dewasa. E. Pemfigoid bulosa adalah penyakit autoimun yang menyebabkan lepuh besar pada kulit, tetapi biasanya terjadi pada orang tua dan tidak disebabkan oleh obat.","optionExplanations":["SJS biasanya mengenai <10% permukaan tubuh menurut sumber; lesi pada kasus ini hampir seluruh tubuh sehingga lebih konsisten dengan TEN.","Pemfigus vulgaris merupakan penyakit autoimun dengan bula kulit/mukosa, tetapi sumber menilai tidak sesuai dengan pemicu obat dan tanda vital abnormal pada kasus.","SSSS merupakan infeksi bakteri dengan eksfoliasi kulit yang sumber sebutkan biasanya terjadi pada bayi dan anak-anak, bukan dewasa.","TEN sesuai dengan reaksi obat fenitoin, lesi luas hampir seluruh tubuh, bula/erosi, dan keterlibatan mukosa.","Pemfigoid bulosa biasanya mengenai orang tua dan menurut sumber tidak disebabkan oleh obat seperti pada kasus ini."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 15"},
  {"id":1016,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 32 tahun datang ke puskesmas dengan keluhan keputihan berwarna kuning kehijaun disertai rasa gatal dan nyeri saat berhubungan. Keluhan keputihan dirasakan sejak 1 minggu lalu yang semakin banyak. Pemeriksaan tanda vital TD 120/80, HR 80, RR 20, T 36,3. Pada pemeriksaan cervix ditemukan granulasi warna merah, pH vagina 6, sediaan basah menunjukkan protozoa berflagel. Tatalaksana yang paling tepat untuk pasien adalah?","options":["Metronidazole 1 g PO dosis tunggal","Flukonazol 150 mg PO dosis tunggal","Klindamisin 2 x 300 mg PO selama 7 hari","Metronidazole 2 x 500 mg PO selama 7 hari","Nistatin 100.000 IU intravaginal selama 7 hari"],"answer":3,"explanation":"Jawaban: D Pembahasan: Pasien ini didiagnosis dengan trichomoniasis, yang ditunjukkan oleh keputihan berwarna kuning kehijaun, rasa gatal, nyeri saat berhubungan, dan temuan protozoa berflagel pada sediaan basah. Pengobatan pilihan untuk trichomoniasis adalah metronidazole 2 x 500 mg per oral selama 7 hari (Jawaban D). Jawaban A kurang tepat karena meskipun metronidazole adalah obat pilihan, dosis yang diberikan tidak cukup. Jawaban B, C, dan E kurang tepat karena flukonazol dan klindamisin biasanya digunakan untuk mengobati infeksi jamur (misalnya, candidiasis), dan nistatin digunakan untuk mengobati infeksi jamur lokal. Semua obat ini tidak efektif terhadap trichomonas.","optionExplanations":["Metronidazole 1 g PO dosis tunggal disebut sumber kurang tepat karena dosis yang diberikan tidak cukup.","Flukonazol 150 mg PO dosis tunggal digunakan untuk infeksi jamur dan menurut sumber tidak efektif terhadap trichomonas.","Klindamisin 2 x 300 mg PO selama 7 hari menurut sumber bukan terapi untuk trichomonas; sumber mengelompokkannya dengan pilihan yang tidak efektif terhadap trichomonas.","Metronidazole 2 x 500 mg PO selama 7 hari merupakan terapi pilihan untuk trichomoniasis dan merupakan kunci pada sumber.","Nistatin digunakan untuk infeksi jamur lokal dan menurut sumber tidak efektif terhadap trichomonas."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 16"},
  {"id":1017,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 21 tahun datang ke puskesmas dengan keluhan perih pada bagian bibir dalam sejak 3 hari lalu. Riwayat pasien mengkonsumsi gorengan. Keluhan dirasa semakin perih ketika terkena makanan asam. Pemeriksaan tanda vital TD 120/80, HR 88, RR 20, T 36,4. Pada pemeriksaan fisik terdapat 5 ulkus dangkal pada bibir bagian dalam dengan nyeri (+). Tatalaksana yang paling tepat untuk pasien adalah?","options":["Krim asiklovir 3%","Krim triamsionolon asetonid 0,1%","Krim ketokonazol 2%","Krim gentamisin 0,1%","Krim permetrin 5%"],"answer":1,"explanation":"Jawaban: B Pembahasan: Pasien dengan gejala ulkus dangkal pada bibir bagian dalam yang nyeri dan diperparah oleh makanan asam kemungkinan besar mengalami stomatitis aftosa rekuren. Kondisi ini biasanya disebabkan oleh trauma, stres, atau makanan tertentu. Krim triamsionolon asetonid 0,1% adalah kortikosteroid topikal yang digunakan untuk mengurangi peradangan dan nyeri pada stomatitis aftosa rekuren. Jawaban lainnya kurang tepat karena: A. Krim asiklovir 3% digunakan untuk infeksi virus herpes, bukan stomatitis aftosa. C. Krim ketokonazol 2% digunakan untuk infeksi jamur, bukan stomatitis aftosa. D. Krim gentamisin 0,1% digunakan untuk infeksi bakteri, bukan stomatitis aftosa. E. Krim permetrin 5% digunakan untuk skabies dan kutu, bukan stomatitis aftosa.","optionExplanations":["Krim asiklovir 3% digunakan untuk infeksi virus herpes, bukan stomatitis aftosa menurut sumber.","Krim triamsionolon asetonid 0,1% merupakan kortikosteroid topikal yang digunakan untuk mengurangi peradangan dan nyeri pada stomatitis aftosa rekuren.","Krim ketokonazol 2% digunakan untuk infeksi jamur, bukan stomatitis aftosa.","Krim gentamisin 0,1% digunakan untuk infeksi bakteri, bukan stomatitis aftosa.","Krim permetrin 5% digunakan untuk skabies dan kutu, bukan stomatitis aftosa."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 17"},
  {"id":1018,"department":"Try Out UKMPPD 1","question":"Seorang pria berusia 25 tahun datang ke puskesmas dengan keluhan kemerahan di kulit yang terasa gatal pada punggung tangan kanan. Keluhan ini sebelumnya sering hilang timbul. Pasien mengaku tidak ada riwayat konsumsi obat-obatan sebelumnya. Pemeriksaan tanda vital TD 120/80, HR 80, RR 20, T 36. Pemeriksaan dermatologis ditemukan lesi berupa papul eritem, multipel, bentuk koin, disertai krusta diatasnya pada dorsum manus dextra. Diagnosis yang sesuai dengan keluhan pasien?","options":["Dermatitis numularis","Dermatitis kontak alergi","Dermatitis kontak iritan","Dermatitis seboroik","Neurodermatitis"],"answer":0,"explanation":"Jawaban: A Pembahasan: Dermatitis numularis adalah kondisi kulit yang ditandai dengan lesi berbentuk koin, eritematosa, dan sering kali disertai gatal. Lesi ini biasanya terjadi di ekstremitas dan dapat hilang timbul. Deskripsi dalam soal sesuai dengan gambaran klinis dermatitis numularis. Dermatitis kontak alergi (B) dan dermatitis kontak iritan (C) biasanya terjadi sebagai reaksi terhadap zat tertentu yang bersentuhan dengan kulit, seperti sabun, deterjen, atau logam. Pasien tidak melaporkan paparan terhadap zat iritan atau alergen. Dermatitis seboroik (D) biasanya terjadi di area kulit yang berminyak, seperti wajah, dada, dan kulit kepala. Lesi biasanya berupa plak eritematosa dengan sisik berminyak dan tebal. Neurodermatitis (E) biasanya terjadi di area yang dapat dijangkau untuk digaruk, seperti lengan, kaki, atau leher. Lesi biasanya berupa plak eritematosa dengan sisik dan lichenifikasi (penebalan kulit) akibat garukan berulang.","optionExplanations":["Dermatitis numularis sesuai dengan lesi berbentuk koin, eritematosa, gatal, mengenai ekstremitas, dan dapat hilang timbul.","Dermatitis kontak alergi biasanya merupakan reaksi terhadap zat yang bersentuhan dengan kulit; sumber menyebut tidak ada riwayat paparan alergen pada kasus.","Dermatitis kontak iritan juga biasanya terkait paparan zat seperti sabun/deterjen; sumber menyebut tidak ada paparan tersebut pada kasus.","Dermatitis seboroik biasanya mengenai area kulit berminyak seperti wajah, dada, dan kulit kepala dengan sisik berminyak.","Neurodermatitis biasanya mengenai area yang mudah digaruk dan dapat menimbulkan lichenifikasi; gambaran ini tidak sesuai dengan lesi koin pada kasus."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 18"},
  {"id":1019,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 24 tahun datang ke puskesmas dengan keluhan rambut rontok sejak 1 minggu yang lalu. Keluhan dirasakan muncul selama pasien belajar untuk mempersiapkan UKMPPD. Keluhan seperti ini sebelumnya disangkal. Pemeriksaan tanda vital TD 110/70, HR 80, RR 20, T 36,2. Pemeriksaan hair pull test (+). Diagnosis yang tepat pada pasien tersebut adalah?","options":["Alopesia areata totalis","Anagen effluvium","Alopesia androgenik","Telogen effluvium","Alopesia areata universalis"],"answer":3,"explanation":"Jawaban: D Pembahasan: Pasien ini memiliki gejala yang khas dari Telogen effluvium, yaitu rambut rontok yang terjadi secara mendadak dan merata di seluruh kepala. Telogen effluvium biasanya terjadi setelah stres fisik atau emosional yang signifikan, seperti persiapan untuk ujian UKMPPD. Hair pull test yang positif juga mendukung diagnosis ini. Alopesia areata totalis (A) dan Alopesia areata universalis (E) adalah bentuk alopesia areata yang lebih parah, di mana rambut rontok dari seluruh kepala atau seluruh tubuh. Alopesia androgenik (C) adalah jenis kebotakan yang paling umum pada pria dan wanita, dan biasanya ditandai dengan penipisan rambut di bagian atas kepala. Anagen effluvium (B) biasanya terjadi sebagai akibat dari kemoterapi atau radiasi, dan menyebabkan rambut rontok dalam fase pertumbuhan (anagen), bukan fase istirahat (telogen) seperti pada Telogen effluvium.","optionExplanations":["Alopesia areata totalis merupakan bentuk alopesia areata berat dengan kerontokan seluruh kulit kepala; gambaran tersebut tidak dijelaskan pada kasus.","Anagen effluvium biasanya terjadi akibat kemoterapi atau radiasi dan menyebabkan rambut rontok pada fase anagen, berbeda dari telogen effluvium.","Alopesia androgenik biasanya berupa penipisan rambut di bagian atas kepala dan tidak sesuai dengan kerontokan mendadak setelah stres yang dijelaskan.","Telogen effluvium sesuai dengan kerontokan mendadak, hair pull test positif, dan stres emosional saat persiapan UKMPPD.","Alopesia areata universalis merupakan bentuk berat dengan kerontokan rambut seluruh tubuh; gambaran tersebut tidak ada pada kasus."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 19"},
  {"id":1020,"department":"Try Out UKMPPD 1","question":"Seorang anak perempuan usia 12 bulan datang dibawa orangtuanya ke poliklinik RS karena terdapat keluhan kulit kering seperti bersisik pada seluruh tubuh. Keluarga ada yang mempunyai keluhan yang sama. Keluhan ini sebenarnya sudah dialami sejak anak usia 6 bulan, namun keluarga biarkan dan diberikan pelembab bayi, namun tidak ada perbaikan. Pemeriksaan tanda vital TD 110/70, HR 88, RR 20, T 37. Pada pemeriksaan fisik tampak kulit bersisik kering seperti sisik ikan, namun tidak mengenai bagian lipat siku dan ketiak. Tatalaksana yang paling tepat untuk pasien adalah?","options":["Emolien","Asam salisilat","Hidrokortison","Ketokonazol","Gentamisin"],"answer":1,"explanation":"Soal ini menggambarkan kasus seorang anak perempuan yang mengalami kondisi kulit bersisik kering yang dikenal sebagai iktiosis vulgaris. Kondisi ini adalah kelainan genetik yang menyebabkan gangguan pada proses keratinisasi kulit, sehingga kulit tampak bersisik seperti ikan. Gejala ini biasanya muncul pada masa bayi atau anak-anak dan dapat memburuk pada musim dingin atau lingkungan yang kering. Dalam kasus ini, tatalaksana yang paling tepat adalah penggunaan asam salisilat. Asam salisilat bekerja sebagai keratolitik, yang membantu mengelupas lapisan kulit mati dan mengurangi penumpukan sisik pada permukaan kulit. Oleh karena itu, jawaban yang benar adalah B. Asam salisilat. Pilihan lain kurang tepat karena: A. Emolien: Emolien memang dapat digunakan untuk melembabkan kulit dan mengurangi kekeringan, tetapi dalam kasus iktiosis vulgaris, emolien saja sering kali tidak cukup efektif untuk mengatasi penumpukan sisik yang tebal. Asam salisilat lebih efektif karena memiliki sifat keratolitik yang dapat membantu menghilangkan sisik. C. Hidrokortison: Hidrokortison adalah kortikosteroid topikal yang digunakan untuk mengurangi peradangan dan gatal-gatal pada kondisi kulit inflamasi seperti dermatitis atau eksim. Namun, iktiosis vulgaris bukanlah kondisi inflamasi, sehingga penggunaan hidrokortison tidak akan efektif dalam mengatasi sisik yang disebabkan oleh gangguan keratinisasi. D. Ketokonazol: Ketokonazol adalah agen antijamur yang digunakan untuk mengobati infeksi jamur pada kulit. Karena iktiosis vulgaris bukan disebabkan oleh infeksi jamur, ketokonazol tidak akan memberikan manfaat dalam tatalaksana kondisi ini. E. Gentamisin: Gentamisin adalah antibiotik topikal yang digunakan untuk mengobati infeksi bakteri pada kulit. Seperti halnya ketokonazol, gentamisin tidak akan efektif dalam mengatasi iktiosis vulgaris karena kondisi ini tidak disebabkan oleh infeksi bakteri. Dengan demikian, asam salisilat adalah pilihan yang paling tepat untuk mengatasi gejala kulit bersisik pada iktiosis vulgaris, karena kemampuannya untuk mengelupas lapisan kulit mati dan mengurangi penumpukan sisik.","optionExplanations":["Emolien dapat melembabkan kulit dan mengurangi kekeringan, tetapi sumber menyebut emolien saja sering tidak cukup untuk sisik tebal pada iktiosis vulgaris.","Asam salisilat merupakan keratolitik yang menurut sumber membantu mengelupas kulit mati dan mengurangi penumpukan sisik.","Hidrokortison digunakan untuk kondisi inflamasi seperti dermatitis/eksim; sumber menyebut iktiosis vulgaris bukan kondisi inflamasi.","Ketokonazol merupakan antijamur dan tidak bermanfaat untuk iktiosis vulgaris yang bukan disebabkan infeksi jamur.","Gentamisin merupakan antibiotik topikal dan tidak mengatasi gangguan keratinisasi iktiosis vulgaris."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 20"},
  {"id":1021,"department":"Try Out UKMPPD 1","question":"Seorang wanita berusia 28 tahun G2P1A0 datang bersama suaminya ke poliklinik RS dengan keluhan muncul benjolan pada kelamin sejak 1 bulan yang lalu. Benjolan awalnya dirasakan di sekitar kemaluan lalu menyebar hingga ke daerah bokong. Pemeriksaan tanda vital TD 110/70, HR 80, RR 20, T 36,4. Pada pemeriksaan dermatologis didapatkan benjolan seperti papul, permukaan verukosa, berbentuk seperti jengger ayam, tes acetowhite (+). Tatalaksana yang tepat untuk pasien adalah?","options":["Podofilotoksin 0,5%","Podofilin 25%","Insisi","Asiklovir 3%","TCA 80-90%"],"answer":4,"explanation":"Soal ini menggambarkan kasus seorang wanita dengan lesi pada area genital yang memiliki karakteristik khas dari kondiloma akuminata, atau kutil kelamin, yang disebabkan oleh infeksi Human Papillomavirus (HPV). Lesi ini tampak sebagai papul dengan permukaan verukosa dan berbentuk seperti jengger ayam, serta menunjukkan hasil positif pada tes acetowhite, yang merupakan tes diagnostik untuk HPV. Tatalaksana yang tepat untuk kondisi ini adalah aplikasi asam trikloroasetat (TCA) 80-90%, yang bertindak sebagai agen kaustik untuk menghancurkan jaringan kutil secara kimiawi. Pilihan lain kurang tepat karena: A. Podofilotoksin 0,5%: Podofilotoksin adalah agen antimitotik yang digunakan untuk mengobati kondiloma akuminata, tetapi biasanya digunakan untuk pengobatan mandiri oleh pasien di rumah dan lebih cocok untuk lesi yang lebih kecil. Dalam pengaturan klinis, terutama untuk lesi yang lebih besar atau lebih ekstensif seperti yang dijelaskan dalam kasus ini, TCA lebih sering dipilih karena efektivitasnya yang lebih tinggi dalam menghancurkan jaringan kutil dengan cepat. B. Podofilin 25%: Podofilin adalah agen yang juga digunakan untuk pengobatan kutil kelamin, namun, penggunaannya memerlukan aplikasi oleh tenaga medis dan tidak dianjurkan untuk digunakan pada area yang luas atau sensitif karena risiko toksisitas dan efek samping sistemik. Selain itu, podofilin tidak lagi menjadi pilihan utama dalam banyak protokol pengobatan modern. C. Insisi: Insisi bukanlah metode yang tepat untuk menangani kondiloma akuminata. Kutil kelamin biasanya tidak diangkat dengan pembedahan karena metode ini bisa menyebabkan perdarahan dan infeksi, serta tidak efektif untuk lesi multipel atau yang tersebar luas. D. Asiklovir 3%: Asiklovir adalah obat antivirus yang digunakan untuk mengobati infeksi herpes simplex, bukan untuk HPV. Oleh karena itu, asiklovir tidak efektif dalam mengobati kutil kelamin yang disebabkan oleh HPV. Dengan mempertimbangkan karakteristik lesi dan pilihan pengobatan yang paling efektif, TCA 80-90% adalah pilihan yang tepat untuk tatalaksana kondiloma akuminata dalam kasus ini.","optionExplanations":["Podofilotoksin 0,5% merupakan agen antimitotik untuk kondiloma akuminata; sumber menyebutnya lebih cocok untuk penggunaan mandiri dan lesi lebih kecil.","Podofilin 25% juga dapat digunakan untuk kutil kelamin, tetapi sumber menyebut penggunaannya pada area luas/sensitif berisiko toksisitas dan bukan pilihan utama banyak protokol modern.","Insisi bukan metode yang tepat untuk kondiloma akuminata multipel/tersebar luas menurut sumber karena risiko perdarahan dan infeksi.","Asiklovir 3% adalah antivirus untuk herpes simplex dan tidak efektif untuk kutil kelamin akibat HPV.","TCA 80–90% merupakan pilihan yang disebut tepat oleh sumber untuk kondiloma akuminata dan bekerja sebagai agen kaustik."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 21"},
  {"id":1022,"department":"Try Out UKMPPD 1","question":"Seorang anak perempuan berusia 14 tahun datang ke puskesmas diantar orang tuanya dengan keluhan gatal pada kedua sela jarinya sejak 4 hari yang lalu. Keluhan gatal dirasakan memberat terutama pada malam hari. Pasien mengaku sebelumnya teman satu pondok memiliki keluhan serupa. Pemeriksaan tanda vital TD 120/80, HR 80, RR 20, T 36,3. Pada pemeriksaan status lokalis didapatkan papul vesikel, beberapa membentuk lesi seperti terowongan, disertai ekskoriasi. Tatalaksana yang tepat untuk pasien adalah?","options":["Sulfur presipitatum 15%","Permetrin 1%","Sulfur presipitatum 20%","Permetrin 5%","Gameksan 10%"],"answer":3,"explanation":"Jawaban: D Pembahasan: Pasien ini diduga menderita skabies, yang ditandai dengan gatal yang memburuk di malam hari, lesi papul vesikel, dan lesi yang tampak seperti terowongan. Skabies adalah infeksi parasit yang disebabkan oleh Sarcoptes scabiei, dan dapat menyebar melalui kontak langsung dengan orang yang terinfeksi. Pengobatan pilihan pertama untuk skabies adalah permetrin 5%, yang diaplikasikan ke seluruh tubuh dari leher ke bawah dan dibiarkan selama 8-14 jam sebelum dibilas. Sulfur presipitatum 15% dan 20% (pilihan A dan C) juga dapat digunakan untuk mengobati skabies, tetapi biasanya digunakan sebagai alternatif jika pasien alergi terhadap permetrin atau jika permetrin tidak tersedia. Permetrin 1% (pilihan B) biasanya digunakan untuk mengobati kutu kepala, bukan skabies. Gameksan 10% (pilihan E) adalah obat antijamur, bukan obat untuk skabies.","optionExplanations":["Sulfur presipitatum 15% dapat digunakan sebagai alternatif terapi skabies menurut sumber, terutama bila permetrin tidak tersedia atau tidak dapat digunakan.","Permetrin 1% menurut sumber lebih digunakan untuk kutu kepala, bukan skabies.","Sulfur presipitatum 20% juga disebut dapat digunakan sebagai alternatif untuk skabies.","Permetrin 5% merupakan terapi pilihan pertama untuk skabies pada sumber, dengan aplikasi dari leher ke bawah selama 8–14 jam.","Gameksan 10% disebut sumber sebagai obat antijamur, bukan terapi skabies."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 22"},
  {"id":1023,"department":"Try Out UKMPPD 1","question":"Seorang pria berusia 40 tahun datang ke puskesmas dengan keluhan bercak putih pada mulut. Pasien memiliki riwayat DM dan merupakan perokok aktif. Pemeriksaan tanda vital TD 120/80, HR 80, RR 20, T 37,8. Pemeriksaan status lokalis terdapat plak putih tebal di palatum durum hingga palatum mole yang dapat dikerok menggunakan spatula lidah, perdarahan (+). Diagnosis yang tepat pada pasien adalah?","options":["Kandidiasis eritematosa","Oral thrush","Leukoplakia","Denture stomatitis","Perleche"],"answer":1,"explanation":"Jawaban: C Pembahasan: Pasien dengan riwayat DM dan perokok aktif yang datang dengan keluhan bercak putih pada mulut yang dapat dikerok dan menimbulkan perdarahan, sangat mungkin mengidap Candidiasis oral/Oral thrush. Kondisi ini sering terjadi pada perokok dan penderita DM. A. Kandidiasis eritematosa biasanya menimbulkan bercak merah, bukan putih, dan sering terasa sakit atau nyeri. C. Leukoplakia: Bercak tidak dapat diangkat. D. Denture stomatitis biasanya terjadi pada pengguna gigi palsu dan ditandai dengan kemerahan dan pembengkakan di bawah gigi palsu. E. Perleche (atau cheilitis angular) adalah kondisi yang ditandai dengan retakan dan kemerahan di sudut mulut.","optionExplanations":["Kandidiasis eritematosa biasanya menimbulkan bercak merah, bukan plak putih yang dapat dikerok.","Oral thrush/kandidiasis oral sesuai dengan plak putih yang dapat dikerok dan menimbulkan perdarahan; ini juga merupakan diagnosis yang disebut pada pembahasan sumber.","Leukoplakia menurut sumber merupakan bercak yang tidak dapat diangkat, berbeda dari lesi yang dapat dikerok pada kasus.","Denture stomatitis biasanya pada pengguna gigi palsu dan berupa kemerahan/pembengkakan di bawah gigi palsu.","Perleche/cheilitis angular ditandai retakan dan kemerahan di sudut mulut."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 24"},
  {"id":1024,"department":"Try Out UKMPPD 1","question":"Seorang perempuan berusia 14 tahun datang ke poliklinik dengan keluhan jerawat pada wajah. Pasien mengaku awalnya jerawat hanya sedikit lalu beberapa hari ini bertambah banyak sebelum menstruasi. Pemeriksaan tanda vital TD 110/70, HR 80, RR 20, T 36,4. Pada pemeriksaan dermatologis didapatkan komedo","options":["Kompres","Antibiotik","Retinoid","Benzoyl peroxide","Isotretinoin"],"answer":3,"explanation":"Pembahasan soal pada sumber berlanjut pada halaman berikutnya; entri ini mempertahankan teks yang berhasil diekstrak dari dokumen dan kunci yang tercantum.","optionExplanations":["Sumber yang tersedia pada ekstraksi tidak memberikan pembahasan terpisah untuk opsi ini.","Sumber yang tersedia pada ekstraksi tidak memberikan pembahasan terpisah untuk opsi ini.","Sumber yang tersedia pada ekstraksi tidak memberikan pembahasan terpisah untuk opsi ini.","Kunci pada dokumen untuk Soal No 25 tercatat sebagai D.","Sumber yang tersedia pada ekstraksi tidak memberikan pembahasan terpisah untuk opsi ini."],"source":"Pembahasan Try Out UKMPPD 1, Soal No 25"},
];
